/**
 * frontend/src/Dashboard.jsx - VERSION CORRIGÉE
 * À REMPLACER
 * - Pas de refresh automatique
 * - Meilleure gestion des erreurs
 * - Logs pour debug
 */

import React, { useState, useEffect } from 'react';
import { attendanceAPI, studentsAPI } from './api_service';

const COLORS = {
  primary: '#4F46E5',
  success: '#10B981',
  danger: '#EF4444',
  warning: '#F59E0B',
  textMain: '#1E293B',
  textMuted: '#64748B',
  border: '#E2E8F0',
  background: '#F8FAFC',
  surface: '#FFFFFF'
};

const Dashboard = () => {
  // ============ STATE ============
  const [stats, setStats] = useState(null);
  const [attendanceLog, setAttendanceLog] = useState([]);
  const [statusList, setStatusList] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [lastUpdated, setLastUpdated] = useState(null);

  // ============ LOAD DATA ============
  const loadData = async () => {
    try {
      console.log('📊 [DASHBOARD] Loading data...');
      setLoading(true);
      setError(null);

      // Charger les stats
      console.log('📥 [DASHBOARD] Fetching stats...');
      const statsRes = await attendanceAPI.getStats();
      console.log('✅ [DASHBOARD] Stats loaded:', statsRes.data);
      setStats(statsRes.data);

      // Charger l'attendance du jour
      console.log('📥 [DASHBOARD] Fetching today\'s attendance...');
      const logRes = await attendanceAPI.getTodayLog();
      console.log('✅ [DASHBOARD] Attendance log loaded:', logRes.data);
      setAttendanceLog(logRes.data.records || []);

      // Charger le status
      console.log('📥 [DASHBOARD] Fetching status...');
      const statusRes = await attendanceAPI.getStatus();
      console.log('✅ [DASHBOARD] Status loaded:', statusRes.data);
      setStatusList(statusRes.data.students || []);

      setLastUpdated(new Date().toLocaleTimeString());
      console.log('✅ [DASHBOARD] All data loaded successfully');
    } catch (err) {
      const errorMsg = err.response?.data?.error || err.message || 'Failed to load data';
      console.error('❌ [DASHBOARD] Error loading data:', errorMsg);
      setError(errorMsg);
    } finally {
      setLoading(false);
    }
  };

  // ============ INITIALIZATION ============
  // Charger les données au montage SEULEMENT (pas de refresh auto)
  useEffect(() => {
    console.log('🎬 [DASHBOARD] Component mounted');
    loadData();

    // Cleanup
    return () => {
      console.log('🛑 [DASHBOARD] Component unmounted');
    };
  }, []);

  // ============ RENDER ============

  if (error) {
    return (
      <div style={styles.container}>
        <div style={styles.errorCard}>
          <div style={styles.errorIcon}>⚠️</div>
          <h3 style={styles.errorTitle}>Erreur lors du chargement</h3>
          <p style={styles.errorText}>{error}</p>
          <button
            onClick={loadData}
            style={styles.retryBtn}
          >
            🔄 Réessayer
          </button>
        </div>
      </div>
    );
  }

  if (loading) {
    return (
      <div style={styles.container}>
        <div style={styles.loadingCard}>
          <div style={styles.spinner}></div>
          <p>Chargement des données...</p>
        </div>
      </div>
    );
  }

  return (
    <div style={styles.container}>
      {/* Header avec refresh manuel */}
      <div style={styles.header}>
        <div>
          <h2 style={styles.title}>Vue d'ensemble</h2>
          {lastUpdated && (
            <p style={styles.subtitle}>
              Dernière mise à jour: {lastUpdated}
            </p>
          )}
        </div>
        <button
          onClick={loadData}
          style={styles.refreshBtn}
          disabled={loading}
        >
          🔄 Rafraîchir
        </button>
      </div>

      {/* STAT CARDS */}
      <div style={styles.statsGrid}>
        <StatCard
          icon="👥"
          label="Étudiants Actifs"
          value={stats?.active_students || 0}
          color={COLORS.primary}
        />
        <StatCard
          icon="✅"
          label="Présents Aujourd'hui"
          value={stats?.present_today || 0}
          color={COLORS.success}
        />
        <StatCard
          icon="❌"
          label="Absents Aujourd'hui"
          value={stats?.absent_today || 0}
          color={COLORS.danger}
        />
        <StatCard
          icon="📊"
          label="Taux de Présence"
          value={
            stats?.active_students > 0
              ? `${((stats?.present_today / stats?.active_students) * 100).toFixed(1)}%`
              : '0%'
          }
          color={COLORS.warning}
        />
      </div>

      {/* MAIN CONTENT - 2 COLONNES */}
      <div style={styles.mainGrid}>
        {/* ATTENDANCE LOG */}
        <div style={styles.section}>
          <h3 style={styles.sectionTitle}>📋 Registre Récent</h3>

          {attendanceLog.length === 0 ? (
            <div style={styles.emptyState}>
              <p>Aucun enregistrement aujourd'hui</p>
            </div>
          ) : (
            <div style={styles.table}>
              <div style={styles.tableHeader}>
                <div style={{ flex: 2 }}>Nom</div>
                <div style={{ flex: 1 }}>Confiance</div>
                <div style={{ flex: 1 }}>Heure</div>
              </div>

              {attendanceLog.slice(0, 10).map((record, idx) => (
                <div key={idx} style={styles.tableRow}>
                  <div style={{ flex: 2 }}>{record.student}</div>
                  <div style={{ flex: 1 }}>
                    <ConfidenceBadge confidence={record.confidence} />
                  </div>
                  <div style={{ flex: 1 }}>{record.timestamp}</div>
                </div>
              ))}
            </div>
          )}
        </div>

        {/* STATUS SUMMARY */}
        <div style={styles.section}>
          <h3 style={styles.sectionTitle}>✅ Résumé d'Aujourd'hui</h3>

          <div style={styles.summaryBox}>
            <SummaryItem
              label="Total d'étudiants"
              value={statusList.length}
              color={COLORS.primary}
            />
            <SummaryItem
              label="Présents"
              value={statusList.filter(s => s.present).length}
              color={COLORS.success}
            />
            <SummaryItem
              label="Absents"
              value={statusList.filter(s => !s.present).length}
              color={COLORS.danger}
            />
            {stats?.summary && (
              <>
                <SummaryItem
                  label="Confiance Moyenne"
                  value={`${(stats.summary.avg_confidence * 100).toFixed(1)}%`}
                  color={COLORS.warning}
                />
              </>
            )}
          </div>
        </div>
      </div>

      {/* FULL STATUS TABLE */}
      <div style={styles.section}>
        <h3 style={styles.sectionTitle}>👥 État de Tous les Étudiants</h3>

        {statusList.length === 0 ? (
          <div style={styles.emptyState}>
            <p>Aucun étudiant enregistré</p>
          </div>
        ) : (
          <div style={styles.table}>
            <div style={styles.tableHeader}>
              <div style={{ flex: 2 }}>Nom</div>
              <div style={{ flex: 2 }}>Email</div>
              <div style={{ flex: 1 }}>Status</div>
            </div>

            {statusList.map((student, idx) => (
              <div key={idx} style={styles.tableRow}>
                <div style={{ flex: 2 }}>{student.name}</div>
                <div style={{ flex: 2, fontSize: '0.85rem', color: COLORS.textMuted }}>
                  {student.email}
                </div>
                <div style={{ flex: 1 }}>
                  <StatusBadge present={student.present} />
                </div>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
};

// ============ COMPONENTS ============

const StatCard = ({ icon, label, value, color }) => (
  <div style={{ ...styles.statCard, borderLeft: `4px solid ${color}` }}>
    <div style={styles.statIcon}>{icon}</div>
    <div style={styles.statContent}>
      <p style={styles.statLabel}>{label}</p>
      <p style={{ ...styles.statValue, color }}>{value}</p>
    </div>
  </div>
);

const ConfidenceBadge = ({ confidence }) => {
  let bgColor, textColor;

  if (confidence >= 0.8) {
    bgColor = '#DCFCE7';
    textColor = '#166534';
  } else if (confidence >= 0.6) {
    bgColor = '#FEF3C7';
    textColor = '#92400E';
  } else {
    bgColor = '#FEE2E2';
    textColor = '#991B1B';
  }

  return (
    <span
      style={{
        padding: '4px 8px',
        backgroundColor: bgColor,
        color: textColor,
        borderRadius: '4px',
        fontSize: '0.85rem',
        fontWeight: 500
      }}
    >
      {(confidence * 100).toFixed(1)}%
    </span>
  );
};

const StatusBadge = ({ present }) => (
  <span
    style={{
      padding: '6px 12px',
      backgroundColor: present ? '#DCFCE7' : '#FEE2E2',
      color: present ? '#166534' : '#991B1B',
      borderRadius: '6px',
      fontSize: '0.9rem',
      fontWeight: 600
    }}
  >
    {present ? '✅ Présent' : '❌ Absent'}
  </span>
);

const SummaryItem = ({ label, value, color }) => (
  <div style={styles.summaryItem}>
    <p style={styles.summaryLabel}>{label}</p>
    <p style={{ ...styles.summaryValue, color }}>{value}</p>
  </div>
);

// ============ STYLES ============

const styles = {
  container: {
    padding: '20px',
    maxWidth: '1400px',
    margin: '0 auto'
  },

  header: {
    display: 'flex',
    justifyContent: 'space-between',
    alignItems: 'center',
    marginBottom: '30px'
  },

  title: {
    margin: 0,
    fontSize: '1.8rem',
    fontWeight: 800,
    color: COLORS.textMain
  },

  subtitle: {
    margin: '8px 0 0 0',
    fontSize: '0.9rem',
    color: COLORS.textMuted
  },

  refreshBtn: {
    padding: '10px 20px',
    backgroundColor: COLORS.primary,
    color: 'white',
    border: 'none',
    borderRadius: '8px',
    fontWeight: 600,
    cursor: 'pointer',
    transition: 'all 0.2s',
    fontSize: '0.95rem'
  },

  statsGrid: {
    display: 'grid',
    gridTemplateColumns: 'repeat(auto-fit, minmax(250px, 1fr))',
    gap: '20px',
    marginBottom: '30px'
  },

  statCard: {
    padding: '20px',
    backgroundColor: COLORS.surface,
    borderRadius: '12px',
    border: `1px solid ${COLORS.border}`,
    display: 'flex',
    gap: '15px',
    boxShadow: '0 1px 3px rgba(0,0,0,0.05)'
  },

  statIcon: {
    fontSize: '2rem'
  },

  statContent: {
    flex: 1
  },

  statLabel: {
    margin: 0,
    fontSize: '0.85rem',
    color: COLORS.textMuted,
    fontWeight: 500
  },

  statValue: {
    margin: '8px 0 0 0',
    fontSize: '1.8rem',
    fontWeight: 700
  },

  mainGrid: {
    display: 'grid',
    gridTemplateColumns: '1fr 1fr',
    gap: '20px',
    marginBottom: '30px'
  },

  section: {
    backgroundColor: COLORS.surface,
    borderRadius: '12px',
    border: `1px solid ${COLORS.border}`,
    padding: '20px',
    boxShadow: '0 1px 3px rgba(0,0,0,0.05)'
  },

  sectionTitle: {
    margin: '0 0 20px 0',
    fontSize: '1.2rem',
    fontWeight: 700,
    color: COLORS.textMain
  },

  table: {
    borderCollapse: 'collapse',
    width: '100%'
  },

  tableHeader: {
    display: 'flex',
    padding: '12px',
    backgroundColor: '#F1F5F9',
    borderRadius: '8px 8px 0 0',
    fontWeight: 600,
    fontSize: '0.9rem',
    color: COLORS.textMuted,
    borderBottom: `1px solid ${COLORS.border}`
  },

  tableRow: {
    display: 'flex',
    padding: '12px',
    borderBottom: `1px solid ${COLORS.border}`,
    alignItems: 'center',
    fontSize: '0.95rem',
    color: COLORS.textMain
  },

  emptyState: {
    padding: '40px 20px',
    textAlign: 'center',
    color: COLORS.textMuted
  },

  loadingCard: {
    display: 'flex',
    flexDirection: 'column',
    alignItems: 'center',
    justifyContent: 'center',
    padding: '60px 20px',
    color: COLORS.textMuted
  },

  spinner: {
    width: '40px',
    height: '40px',
    border: `3px solid ${COLORS.border}`,
    borderTop: `3px solid ${COLORS.primary}`,
    borderRadius: '50%',
    animation: 'spin 1s linear infinite',
    marginBottom: '20px'
  },

  errorCard: {
    display: 'flex',
    flexDirection: 'column',
    alignItems: 'center',
    justifyContent: 'center',
    padding: '60px 20px',
    backgroundColor: '#FEE2E2',
    borderRadius: '12px',
    border: `2px solid ${COLORS.danger}`
  },

  errorIcon: {
    fontSize: '3rem',
    marginBottom: '20px'
  },

  errorTitle: {
    margin: 0,
    fontSize: '1.3rem',
    fontWeight: 700,
    color: COLORS.danger,
    marginBottom: '10px'
  },

  errorText: {
    margin: '0 0 20px 0',
    color: '#991B1B',
    textAlign: 'center'
  },

  retryBtn: {
    padding: '10px 20px',
    backgroundColor: COLORS.danger,
    color: 'white',
    border: 'none',
    borderRadius: '8px',
    fontWeight: 600,
    cursor: 'pointer',
    fontSize: '0.95rem'
  },

  summaryBox: {
    display: 'grid',
    gridTemplateColumns: '1fr',
    gap: '15px'
  },

  summaryItem: {
    padding: '15px',
    backgroundColor: '#F8FAFC',
    borderRadius: '8px',
    border: `1px solid ${COLORS.border}`
  },

  summaryLabel: {
    margin: 0,
    fontSize: '0.9rem',
    color: COLORS.textMuted,
    fontWeight: 500,
    marginBottom: '5px'
  },

  summaryValue: {
    margin: 0,
    fontSize: '1.5rem',
    fontWeight: 700
  }
};

export default Dashboard;
